import{_ as p,W as o,s as d,u as l,ah as u,I as a,w as e,Z as t,A as i}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const f=JSON.parse('{"title":"如何修复 Linux 中扬声器发出的嗡嗡声 | LCTT x X-CMD","titleTemplate":false,"description":"如何修复 Linux 中扬声器发出的嗡嗡声 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何修复 Linux 中扬声器发出的嗡嗡声 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修复 Linux 中扬声器发出的嗡嗡声 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221126.1 ⭐️ How I Fixed Buzzing Noise Coming from Speakers in Linux","title":"如何修复 Linux 中扬声器发出的嗡嗡声","tag":"202301"},"relativePath":"202301/20221126.1 ⭐️ How I Fixed Buzzing Noise Coming from Speakers in Linux.md","filePath":"[post].md"}'),r={name:"202301/20221126.1 ⭐️ How I Fixed Buzzing Noise Coming from Speakers in Linux.md"};function g(b,s,h,m,x,c){const n=o("Link");return l(),d("div",null,[s[20]||(s[20]=u('<h1 id="如何修复-linux-中扬声器发出的嗡嗡声" tabindex="-1">如何修复 Linux 中扬声器发出的嗡嗡声 <a class="header-anchor" href="#如何修复-linux-中扬声器发出的嗡嗡声" aria-label="Permalink to 如何修复 Linux 中扬声器发出的嗡嗡声">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/05/150250sqbeq35bh699r157.jpg" alt=""></p><p>我使用笔记本电脑很长时间了，但最近才切换到台式机上，以便进行远程工作。</p><p>我注意到我的扬声器不断发出嗡嗡声。这很烦人，让我头疼。我开始着手解决这个问题。了解问题的根本原因非常有趣。</p><p>我将分享我在 Linux 中修复扬声器嗡嗡声的经验。我发现它可以在同一硬件上对 Ubuntu、Debian 和 Pop OS 都有效。</p><p>需要考虑的一件事是，如果本指南不适合你，你可能遇到了严重的硬件问题。对于大多数用户来说，给定的方案应该可以解决问题。</p><p><strong>在尝试修复之前</strong></p><p>我试图让事情变得容易安全地遵循。你可以尝试临时修复，如果有效，则将更改永久化。但是，最好使用 Timeshift 制作系统快照。如果你在出现故障时很容易惊慌失措，你可以将系统恢复到之前的状态。</p><p>另外，检查你的声卡。在我的例子中，它是 <code>snd_hda_intel</code>。对于 USB 卡，它可以是 <code>snd_usb_audio</code>。你必须根据你的声卡更改命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat /proc/asound/modules</span></span></code></pre></div><h3 id="linux-中扬声器发出嗡嗡声的原因" tabindex="-1">Linux 中扬声器发出嗡嗡声的原因 <a class="header-anchor" href="#linux-中扬声器发出嗡嗡声的原因" aria-label="Permalink to Linux 中扬声器发出嗡嗡声的原因">​</a></h3><p>梳理了无数的论坛帖子和网站后，我了解了问题的根本原因。这是因为扬声器中的电容放电。它可以通过关闭声卡的省电设置来解决。</p><p>通过关闭省电，你允许系统在这些电容放电时为其充电。这类似于在一直充电时使用电话。</p><p>你可以使用给定的命令检查你的系统是否启用了声卡的省电设置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat /sys/module/snd_hda_intel/parameters/power_save</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/power-saving-setting-in-sound-card-making-buzzing-sound-in-linux.png" alt="power saving setting in sound card making buzzing sound in linux"></p><p>如果你像我一样输出是 <code>1</code>，那么省电功能已打开。因此，让我们看一下方案。</p><p>不用担心。这不会显著影响你的电池百分比，因为所示方法仅适用于声卡。</p><h3 id="尝试修复嗡嗡声问题-临时" tabindex="-1">尝试修复嗡嗡声问题（临时） <a class="header-anchor" href="#尝试修复嗡嗡声问题-临时" aria-label="Permalink to 尝试修复嗡嗡声问题（临时）">​</a></h3><p>我之所以包括临时方法是为了确定嗡嗡声是由于电容放电引起的，还是存在严重的硬件问题。</p><p>如果此临时方案有效，你可以继续使用永久方案。</p><p>第一步是切换到 root 用户：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo su</span></span></code></pre></div><p>然后，执行给定的命令，它应该停止嗡嗡声直到下次启动：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo 0 &gt; /sys/module/snd_hda_intel/parameters/power_save</span></span></code></pre></div><p>如果你使用的是 <strong>USB 声卡</strong>，则必须将 <code>snd_hda_intel</code> 替换为 <code>snd_usb_audio</code>，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo 0 &gt; /sys/module/snd_usb_audio/parameters/power_save</span></span></code></pre></div><p>如果上述技巧解决了问题，那么你必须使变更永久化。否则，下次重启系统时更改将丢失。</p><h3 id="修复嗡嗡声问题-永久" tabindex="-1">修复嗡嗡声问题（永久） <a class="header-anchor" href="#修复嗡嗡声问题-永久" aria-label="Permalink to 修复嗡嗡声问题（永久）">​</a></h3><p>在这里，我将对内核参数进行更改。</p><p>将你的工作目录更改为 <code>/etc/modprobe.d</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd /etc/modprobe.d</span></span></code></pre></div><p>现在，创建一个名为 <code>audio_disable_powersave.conf</code> 的新文件，并使用给定命令使用 nano 文本编辑器打开：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo nano audio_disable_powersave.conf</span></span></code></pre></div><p>并在该文件中放入以下行以永久关闭声卡中的省电设置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>options snd_hda_intel power_save=0</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/fix-buzzing-sound-in-linux.png" alt="fix buzzing sound in linux"></p><p>对于 <strong>USB 声卡</strong>，你需要使用 <code>snd_usb_audio</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>options snd_usb_audio power_save=0</span></span></code></pre></div>',39)),a("p",null,[s[1]||(s[1]=e("现在，")),t(n,{href:"https://linuxhandbook.com/nano-save-exit/"},{default:i(()=>s[0]||(s[0]=[e("保存更改并退出 Nano 文本编辑器")])),_:1}),s[2]||(s[2]=e(" 并按 ")),s[3]||(s[3]=a("code",null,"Ctrl+X",-1)),s[4]||(s[4]=e(" 键。重启你的系统，你就可以享受无噪音的工作空间。"))]),s[21]||(s[21]=a("h3",{id:"总结",tabindex:"-1"},[e("总结 "),a("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to 总结"},"​")],-1)),s[22]||(s[22]=a("p",null,"本指南解释了嗡嗡声的原因以及如何直接解决该问题。",-1)),s[23]||(s[23]=a("p",null,"同样，除了电容放电之外，你可能还有其他问题，因此你应该始终尝试临时方法。",-1)),s[24]||(s[24]=a("p",null,"让我知道你是否能够以这种方式解决 Linux 中扬声器发出的嗡嗡声。",-1)),s[25]||(s[25]=a("hr",null,null,-1)),a("p",null,[s[6]||(s[6]=e("via: ")),t(n,{href:"https://itsfoss.com/buzzing-noise-speaker-linux"},{default:i(()=>s[5]||(s[5]=[e("https://itsfoss.com/buzzing-noise-speaker-linux")])),_:1})]),a("p",null,[s[11]||(s[11]=e("作者：")),t(n,{href:"https://itsfoss.com/author/sagar/"},{default:i(()=>s[7]||(s[7]=[e("Sagar Sharma")])),_:1}),s[12]||(s[12]=e(" 选题：")),t(n,{href:"https://github.com/lkxed"},{default:i(()=>s[8]||(s[8]=[e("lkxed")])),_:1}),s[13]||(s[13]=e(" 译者：")),t(n,{href:"https://github.com/geekpi"},{default:i(()=>s[9]||(s[9]=[e("geekpi")])),_:1}),s[14]||(s[14]=e(" 校对：")),t(n,{href:"https://github.com/wxy"},{default:i(()=>s[10]||(s[10]=[e("wxy")])),_:1})]),a("p",null,[s[17]||(s[17]=e("本文由 ")),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>s[15]||(s[15]=[e("LCTT")])),_:1}),s[18]||(s[18]=e(" 原创编译，")),t(n,{href:"https://linux.cn/"},{default:i(()=>s[16]||(s[16]=[e("Linux中国")])),_:1}),s[19]||(s[19]=e(" 荣誉推出"))])])}const C=p(r,[["render",g]]);export{f as __pageData,C as default};
